  const gatewayReceiptUnsigned = {
    circuitId: hexToBytes("0102030405060708"),
    gatewayId: deriveNodeId(gateway.publicKey),
    clientId: deriveNodeId(bob.publicKey),
    bytesEgress: 5_000_000,
    bytesIngress: 500_000,
    epochStart: 1710000000,
    epochEnd: 1710000060,
  };
  const clientSig = signGatewayReceiptClient({ ...gatewayReceiptUnsigned, gatewaySig: new Uint8Array(64) }, bob.secretKey);
  const gatewaySig = signGatewayReceiptGateway({ ...gatewayReceiptUnsigned, gatewaySig: new Uint8Array(64), clientSig }, gateway.secretKey);
  const gatewayReceipt = { ...gatewayReceiptUnsigned, gatewaySig, clientSig };
