// ─── Suite 08: Frames ──────────────────────────────────────────────────────

function suite08Frames(): VectorFile {
  const vectors: Vector[] = [];
  const alice = testKeypair("alice");
  const bob = testKeypair("bob");

  const frame: Frame = {
    v: FRAME_VERSION,
    cls: "B",
    dst: deriveNodeId(bob.publicKey),
    src: deriveNodeId(alice.publicKey),
    ttl: 16,
    fid: makeFlowId(),
    seq: 1,
    body: hexToBytes("deadbeef"),
  };
  const encoded = encodeFrame(frame);
  vectors.push({
    id: "frame-encode-decode-roundtrip",
    description: "Encode a Class B frame and decode it back. Verifies canonical CBOR round-trip.",
    input: { frame },
    expected: { encodedHex: hex(encoded), decodesToSame: true },
  });

  const forwarded = forwardFrame(frame);
  vectors.push({
    id: "frame-ttl-decrement",
    description: "forwardFrame() decrements TTL by 1. All other fields preserved.",
    input: { frame },
    expected: { originalTtl: frame.ttl, forwardedTtl: forwarded.ttl },
  });

  const zeroTtl: Frame = { ...frame, ttl: 0 };
  let forwardThrew = false;
  try { forwardFrame(zeroTtl); } catch { forwardThrew = true; }
  vectors.push({
    id: "frame-ttl-zero-drops",
    description: "TTL=0 frame must be dropped (shouldDrop=true) and forwardFrame must throw (I7).",
    input: { frame: zeroTtl },
    expected: { shouldDrop: shouldDrop(zeroTtl), forwardThrows: forwardThrew },
  });

  for (const cls of ["A", "B", "C"] as const) {
    const f: Frame = { ...frame, cls };
    vectors.push({
      id: `frame-class-${cls}`,
      description: `Class ${cls} frame encodes/decodes with cls='${cls}'.`,
      input: { cls },
      expected: { encodedHex: hex(encodeFrame(f)), decodedCls: decodeFrame(encodeFrame(f)).cls },
    });
  }

  for (const targetSize of [100, 256, 300, 512, 1000, 1500, 2000]) {
    const body = new Uint8Array(targetSize);
    const { padded, originalLength } = padBody(body);
    vectors.push({
      id: `frame-padding-${targetSize}`,
      description: `Pad ${targetSize}-byte body to next bucket in [256,512,1024,1500]. >1500 not padded.`,
      input: { originalSize: targetSize },
      expected: { paddedLength: padded.length, originalLength, unpaddedMatches: bytesEqual(unpadBody(padded, originalLength), body) },
    });
  }

  return { suite: "frames", specSection: "SNP/0.1 §7", generatedBy: "snp-typescript-reference", generatedAt: now(), vectors };
}

